using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json.Nodes;

namespace YjsSharp.Tests.Compat;

/// <summary>Loads the fixtures generated by real Yjs (tests/fixtures-generator).</summary>
internal static class Fixtures
{
    /// <summary>The fixture files holding document scenarios.</summary>
    public static readonly string[] DocumentFiles =
    {
        "text", "array", "map", "nested", "xml", "subdocs", "snapshots", "relpos", "misc", "random", "large"
    };

    private static readonly ConcurrentDictionary<string, JsonObject> Cache = new ConcurrentDictionary<string, JsonObject>();

    public static string Directory => Path.Combine(AppContext.BaseDirectory, "Compat", "Fixtures");

    public static JsonObject File(string name)
        => Cache.GetOrAdd(name, n => (JsonObject)JsonNode.Parse(System.IO.File.ReadAllText(Path.Combine(Directory, n + ".json")))!);

    public static IEnumerable<JsonObject> Scenarios(string file) => File(file)["scenarios"]!.AsArray().Select(n => (JsonObject)n!);

    /// <summary>A scenario by its "file/name" key.</summary>
    public static JsonObject Scenario(string key)
    {
        var slash = key.IndexOf('/');
        var file  = key.Substring(0, slash);
        var name  = key.Substring(slash + 1);
        return Scenarios(file).Single(s => (string)s["name"]! == name);
    }

    /// <summary>"file/name" keys of every document scenario, as MSTest data rows.</summary>
    public static IEnumerable<object[]> DocumentScenarioKeys()
        => DocumentFiles.SelectMany(f => Scenarios(f).Select(s => new object[] { f + "/" + (string)s["name"]! }));

    public static byte[] Bytes(JsonNode? node) => Convert.FromBase64String((string)node!);
}
